// ─── Import Logic ──────────────────────────────────────────────────────────────
const MOQ = 12; // Minimum order quantity for wholesale

async function importProducts() {
  console.log(`Starting import of ${products.length} products...`);
  let success = 0;
  let failed = 0;
  const errors = [];

  for (let i = 0; i < products.length; i++) {
    const p = products[i];
    const payload = {
      product_id: p.product_id,
      sku: p.sku,
      name: p.name,
      bin_location: p.bin_location,
      buyPrice: p.buyPrice,
      sellPrice: parseFloat((p.buyPrice * 1.4).toFixed(2)),
      stock: 100,
      weight: 0.5,
      description: p.name,
      role: "wholesaler",
      moq: MOQ,
    };

    try {
      const res = await fetch(`${BACKEND_URL}/api/admin/add-product`, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${ADMIN_TOKEN}`,
        },
        body: JSON.stringify(payload),
      });

      if (res.ok) {
        success++;
        console.log(`[${i + 1}/${products.length}] ✓ ${p.name.substring(0, 60)}`);
      } else {
        const err = await res.text();
        failed++;
        errors.push({ product_id: p.product_id, name: p.name, error: err });
        console.error(`[${i + 1}/${products.length}] ✗ ${p.name.substring(0, 60)} → ${res.status}: ${err}`);
      }
    } catch (e) {
      failed++;
      errors.push({ product_id: p.product_id, name: p.name, error: e.message });
      console.error(`[${i + 1}/${products.length}] ✗ ${p.name.substring(0, 60)} → ${e.message}`);
    }

    // Small delay to avoid overwhelming the server
    await new Promise(r => setTimeout(r, 100));
  }

  console.log("\n─────────────────────────────────");
  console.log(`✓ Success: ${success}`);
  console.log(`✗ Failed:  ${failed}`);
  if (errors.length > 0) {
    console.log("\nFailed products:");
    errors.forEach(e => console.log(`  [${e.product_id}] ${e.name.substring(0, 50)} → ${e.error}`));
  }
}

importProducts();
